/*
 * Port of org.schabi.newpipe.database.feed.model.FeedGroupEntity (Room entity `feed_group`).
 */

import { relationalStore } from '@kit.ArkData';
import { colNumber, colString } from '../../../common/db/AppDatabase';
import { FeedGroupIcon } from '../../enums/FeedGroupIcon';

export class FeedGroupEntity {
  static readonly TABLE: string = 'feed_group';

  /** The pseudo group id meaning "every subscription", not a row in this table. */
  static readonly GROUP_ALL_ID: number = -1;

  /** `uid`, the autogenerated primary key. 0 until the row has been inserted. */
  uid: number;
  /** `name` */
  name: string;
  /** `icon_id` — Converters stores FeedGroupIcon.id, which is the enum value itself. */
  icon: FeedGroupIcon;
  /** `sort_order` — assigned by FeedGroupDAO.insert() from nextSortOrder(). */
  sortOrder: number = -1;

  constructor(uid: number, name: string, icon: FeedGroupIcon) {
    this.uid = uid;
    this.name = name;
    this.icon = icon;
  }

  static fromRow(rs: relationalStore.ResultSet): FeedGroupEntity {
    const entity: FeedGroupEntity = new FeedGroupEntity(
      colNumber(rs, 'uid'),
      colString(rs, 'name'),
      colNumber(rs, 'icon_id') as FeedGroupIcon
    );
    entity.sortOrder = colNumber(rs, 'sort_order');
    return entity;
  }

  /** The row without `uid`, so SQLite assigns the autoincrement key on insert. */
  toValuesBucket(): relationalStore.ValuesBucket {
    const values: relationalStore.ValuesBucket = {
      'name': this.name,
      'icon_id': this.icon as number,
      'sort_order': this.sortOrder
    };
    return values;
  }
}
